TOOLS.rylandstree = { type: 'tree', title: 'Rylands v Fletcher checklist', intro: 'Check each element, then the defences.', nodes: {
  start: { q: 'Did the defendant bring the thing onto their land and keep it there for their own purposes?', o: [['Yes', 'danger'], ['No — it occurred naturally', 'nat']] },
  nat: { end: true, tone: 'bad', v: 'Not Rylands', x: 'Consider nuisance (Leakey v National Trust) instead.', cases: ['giles'] },
  danger: { q: 'Would it create an exceptionally high risk if it escaped, and was keeping it an extraordinary, unusual use of land?', o: [['Yes — e.g. bulk chemicals, explosives, water in a reservoir', 'escape'], ['No — ordinary domestic or commercial use', 'natural']] },
  natural: { end: true, tone: 'bad', v: 'Natural use — no liability', x: '', cases: ['rickards', 'transco', 'stannard'] },
  escape: { q: 'Did the thing itself escape from land under the defendant’s control?', o: [['Yes', 'dmg'], ['No — the harm happened on the defendant’s land, or something else escaped', 'noesc']] },
  noesc: { end: true, tone: 'bad', v: 'No escape — no liability', x: '', cases: ['readlyons', 'stannard'] },
  dmg: { q: 'What damage?', o: [['Foreseeable damage to the claimant’s land or property', 'def'], ['Personal injury', 'pi'], ['Damage of an unforeseeable type', 'unf']] },
  pi: { end: true, tone: 'bad', v: 'Not recoverable under Rylands', x: 'Sue in negligence (or public nuisance).', cases: ['transco'] },
  unf: { end: true, tone: 'bad', v: 'Not recoverable', x: '', cases: ['cambridgewater'] },
  def: { q: 'Any defence?', o: [['A stranger’s unforeseeable act caused the escape', 'd1'], ['Extraordinary natural event', 'd2'], ['The claimant consented or it was for common benefit', 'd3'], ['Statute required the activity', 'd4'], ['None', 'liable']] },
  d1: { end: true, tone: 'bad', v: 'Act of a stranger', x: '', cases: ['perry'] },
  d2: { end: true, tone: 'bad', v: 'Act of God', x: '', cases: ['nichols'] },
  d3: { end: true, tone: 'bad', v: 'Consent / common benefit', x: '', cases: ['peters'] },
  d4: { end: true, tone: 'bad', v: 'Statutory authority', x: '', cases: ['greenchelsea'] },
  liable: { end: true, tone: 'good', v: 'Strictly liable', x: 'No need to prove negligence.', cases: ['rylands'] }
} };
TOOLS.vltree = { type: 'tree', title: 'Is the employer vicariously liable?', intro: 'Apply the two-stage test.', nodes: {
  start: { q: 'Stage 1: what is the relationship?', o: [['Employee under a contract of employment', 'st2'], ['Not a formal employee, but work is integral to and for the benefit of the defendant, under its control (e.g. religious order, prisoner, foster carer)', 'akin'], ['An independent contractor running their own business', 'ic']] },
  akin: { end: true, tone: 'mid', v: 'Akin to employment — go on to stage 2', x: '', cases: ['catholic', 'cox'] },
  ic: { q: 'Is there an exception?', o: [['A non-delegable duty (e.g. school to pupils)', 'nd'], ['An extra-hazardous activity', 'eh'], ['Negligent selection or supervision of the contractor', 'sel'], ['None', 'noic']] },
  nd: { end: true, tone: 'good', v: 'Liable — non-delegable duty', x: '', cases: ['woodland'] },
  eh: { end: true, tone: 'good', v: 'Liable — extra-hazardous activity', x: '', cases: ['honeywill'] },
  sel: { end: true, tone: 'good', v: 'Liable for its own negligence (not vicariously)', x: '', cases: ['bottomley'] },
  noic: { end: true, tone: 'bad', v: 'Not liable', x: 'No vicarious liability for genuinely independent contractors.', cases: ['barclays'] },
  st2: { q: 'Stage 2: what did the employee do?', o: [['Their job, but carelessly', 'neg'], ['Their job, in a way the employer had banned', 'ban'], ['Something for their own purposes, away from the job', 'frolic'], ['A deliberate crime or assault', 'crime']] },
  neg: { end: true, tone: 'good', v: 'Liable', x: 'An authorised act done in a wrongful way.', cases: ['century'] },
  ban: { q: 'Was the prohibited act done while carrying out the job, for the employer’s purposes?', o: [['Yes', 'banok'], ['No', 'banno']] },
  banok: { end: true, tone: 'good', v: 'Liable', x: '', cases: ['limpus', 'roseplenty'] },
  banno: { end: true, tone: 'bad', v: 'Not liable', x: '', cases: ['twine'] },
  frolic: { end: true, tone: 'bad', v: 'Not liable — frolic of their own', x: '', cases: ['hilton'] },
  crime: { q: 'Is the crime closely connected with what the employee was employed to do (an unbroken sequence from their duties)?', o: [['Yes', 'cc'], ['No — a personal vendetta or unconnected', 'nocc']] },
  cc: { end: true, tone: 'good', v: 'Liable — close connection', x: '', cases: ['lister', 'mohamud'] },
  nocc: { end: true, tone: 'bad', v: 'Not liable', x: '', cases: ['morrisons2020', 'bxb'] }
} };
TOOLS.defencesort = { type: 'sort', title: 'Which defence?', intro: 'Identify the most relevant defence.', cats: ['Volenti', 'Contributory negligence', 'No defence', 'Illegality'], items: [
  ['A passenger who was not wearing a seatbelt suffers worse injuries in a crash.', 'Contributory negligence', 'Froom v Butcher.'],
  ['A man flies with a pilot he knows is extremely drunk.', 'Volenti', 'Morris v Murray (aircraft — s149 does not apply).'],
  ['A passer-by is injured stopping runaway horses to save children.', 'No defence', 'Rescuers are not volenti — Haynes v Harwood.'],
  ['A passenger urges a drunk, unlicensed rider to drive dangerously to scare people.', 'Illegality', 'Pitts v Hunt.'],
  ['A car passenger accepts a lift from a driver she knows has been drinking.', 'Contributory negligence', 'Owens v Brimmell; volenti barred by s149.'],
  ['Two experienced workers deliberately disobey safety rules to save time.', 'Volenti', 'ICI v Shatwell.'],
  ['A worker knows a crane swings stones overhead but keeps working.', 'No defence', 'Knowledge is not consent — Smith v Baker.']
] };
TOOLS.tortremedysort = { type: 'sort', title: 'Which type of damages or remedy?', intro: 'Classify each.', cats: ['Special damages', 'General damages', 'Nominal damages', 'Injunction'], items: [
  ['Wages lost between the accident and the trial.', 'Special damages', 'Calculable.'],
  ['Compensation for the pain of a broken leg.', 'General damages', 'PSLA.'],
  ['£5 for walking across a lawn causing no damage.', 'Nominal damages', 'Trespass actionable per se.'],
  ['An order to stop a factory making noise at night.', 'Injunction', 'Prohibitory.'],
  ['Loss of future earnings for a claimant who can never work again.', 'General damages', 'Multiplicand × multiplier.'],
  ['Receipts for physiotherapy already paid for.', 'Special damages', 'Past expenses.']
] };
